import{H as e,R as t,U as n,V as r,W as i,j as a,nt as o,ot as s}from"./chunks/framework.DbL7JIvK.js";var c=JSON.parse(`{"title":"Upgrading across versions","description":"Keep cached pages rendering during a Citizen upgrade with the compat flag","frontmatter":{"title":"Upgrading across versions","description":"Keep cached pages rendering during a Citizen upgrade with the compat flag"},"headers":[],"relativePath":"guide/upgrading.md","filePath":"guide/upgrading.md","lastUpdated":1785298256000}`),l={name:`guide/upgrading.md`};function u(a,c,l,u,d,f){let p=s(`CopyOrDownloadAsMarkdownButtons`);return o(),r(`div`,null,[c[0]||=t(`div`,{style:{display:`none`},hidden:`true`,"aria-hidden":`true`,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /guide/upgrading.md for this page in Markdown format`,-1),c[1]||=t(`h1`,{id:`upgrading-across-versions`,tabindex:`-1`},[n(`Upgrading across versions `),t(`a`,{class:`header-anchor`,href:`#upgrading-across-versions`,"aria-label":`Permalink to “Upgrading across versions”`},`​`)],-1),i(p),c[2]||=e(`<p>Citizen serves CSS and JS fresh on every page view, but wikis cache HTML — in the parser cache, CDN or Varnish layers, and <code>$wgUseFileCache</code>. After an upgrade, cached pages generated by the old version meet the new styles, which can break their appearance until every cache has expired or been purged.</p><p>Citizen ships a compatibility layer for exactly this window.</p><h2 id="the-compat-flag" tabindex="-1">The compat flag <a class="header-anchor" href="#the-compat-flag" aria-label="Permalink to “The compat flag”">​</a></h2><p>Set <code>$wgCitizenCompat = true;</code> <strong>before</strong> upgrading. While enabled, Citizen serves compatibility styles so HTML generated by versions up to <strong>6 minor releases</strong> back keeps rendering acceptably — readable and usable, though not always pixel-perfect. The styles ride the normal render-blocking stylesheet, so cached pages are corrected at first paint, including for no-JS visitors.</p><p>The lifecycle:</p><ol><li>Enable the flag.</li><li>Upgrade Citizen.</li><li>Wait out your longest cache lifetime (parser cache expiry, CDN TTL, or file cache age — whichever is longest), purging gradually if you prefer.</li><li>Disable the flag.</li></ol><p>Leaving it enabled costs only a few KB of extra CSS per page view — wikis that deploy continuously can simply leave it on.</p><h2 id="release-cache-statuses" tabindex="-1">Release cache statuses <a class="header-anchor" href="#release-cache-statuses" aria-label="Permalink to “Release cache statuses”">​</a></h2><p>Each release&#39;s notes state its cache status:</p><ul><li><strong>clean</strong> — no cached-HTML impact; upgrade freely.</li><li><strong>covered by compat</strong> — enable the flag across the upgrade.</li><li><strong>purge required</strong> — some pages cannot be bridged by styles alone; plan a cache purge (see below). The flag still covers everything else.</li></ul><h2 id="wiki-farms" tabindex="-1">Wiki farms <a class="header-anchor" href="#wiki-farms" aria-label="Permalink to “Wiki farms”">​</a></h2><p>Enable the flag farm-wide (it is inert for wikis that have no stale pages), upgrade, then purge caches wiki-by-wiki at whatever pace your infrastructure tolerates, and disable the flag when done. If you jumped more than 6 minor releases, expect pages older than the window to need a purge.</p><h2 id="purging-gradually" tabindex="-1">Purging gradually <a class="header-anchor" href="#purging-gradually" aria-label="Permalink to “Purging gradually”">​</a></h2><p>To spread the re-parse load instead of purging everything at once:</p><ul><li>Step <code>maintenance/purgeParserCache.php --age &lt;seconds&gt;</code> down over several days (start with the oldest entries).</li><li>Or stage <code>$wgCacheEpoch</code> forward per wiki, a group of wikis at a time.</li><li>Before a <em>planned</em> upgrade, temporarily lower <code>$wgParserCacheExpireTime</code> a week in advance so no cache entry is older than that when you deploy.</li></ul>`,15)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};